  p120: {"title": "72pcs - Duracell Type C Batteries 1.5V 2030 - NEW", "v": "meh", "cat": "UPS & Power", "name": "72x Duracell C Batteries (Exp 2030)", "sub": "72pcs · Size C · 1.5V Alkaline · Exp 2030 · NEW", "mkt": {"new": "$100–$130", "used": "N/A", "ebay": "$40–$60"}, "notes": "Fresh stock with long dating. The lot weighs about 10lb, so shipping costs $15–$20. It may sell better locally or be used by clients.", "verdict": "Bid $15–$20. Resell $40–$60.", "roi": "1.5x–2x"},
