  p122: {"title": "Adderview Prism AVP4 4-Port Reverse KVM Switch", "v": "nay", "cat": "Networking", "name": "AdderView Prism AVP4 4-Port KVM", "sub": "4-port · Reverse KVM · USB/Video", "mkt": {"new": "N/A", "used": "$25–$60", "ebay": "$25–$50"}, "notes": "A niche multi-viewer/reverse KVM with low eBay demand. Check that the PSU is included.", "verdict": "Bid $3–$6 max.", "roi": "2x"},
  p123: {"title": "Black Box USB 2.0 Over Ethernet Extender Remote & Local Modules", "v": "meh", "cat": "Networking", "name": "Black Box USB 2.0 over Ethernet Extender", "sub": "Local + remote modules · USB 2.0 · Cat5e/6", "mkt": {"new": "N/A", "used": "$40–$100", "ebay": "$30–$60"}, "notes": "Both modules are present, which is required for resale. Check whether the power supplies are included. AV and kiosk integrators buy these.", "verdict": "Bid $5–$10. Resell $30–$60.", "roi": "3x"},
  p124: {"title": "Philips Bodine B50 Emergency Fluorescent Ballast", "v": "nay", "cat": "Industrial & Electrical", "name": "Philips Bodine B50 Emergency Ballast", "sub": "Emergency fluorescent ballast · B50", "mkt": {"new": "$80–$120", "used": "$20–$35", "ebay": "$20–$35"}, "notes": "Fluorescent lighting is being replaced by LED, so demand is shrinking. Electricians replacing units do buy them.", "verdict": "Bid $2–$5 max.", "roi": "2x"},
